"use client"

import { useState } from "react"
import { CartesianGrid, Line, LineChart, XAxis, YAxis } from "recharts"

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./card"
import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "./chart"

/** One sentence on what the chart shows, the field every chart in the set exports. */
export const description = "A bump chart that shows how each channel's rank changes month by month"

// Ranks, not values: 1 is the top. Each month holds every rank once.
const chartData = [
  { month: "January", search: 1, social: 2, email: 3, referral: 4, direct: 5 },
  { month: "February", search: 1, social: 3, email: 2, referral: 4, direct: 5 },
  { month: "March", search: 2, social: 1, email: 3, referral: 5, direct: 4 },
  { month: "April", search: 2, social: 1, email: 4, referral: 3, direct: 5 },
  { month: "May", search: 3, social: 1, email: 4, referral: 2, direct: 5 },
  { month: "June", search: 2, social: 1, email: 5, referral: 3, direct: 4 },
]

const chartConfig = {
  search: {
    label: "Search",
    color: "var(--chart-1)",
  },
  social: {
    label: "Social",
    color: "var(--chart-2)",
  },
  email: {
    label: "Email",
    color: "var(--chart-3)",
  },
  referral: {
    label: "Referral",
    color: "var(--chart-4)",
  },
  direct: {
    label: "Direct",
    color: "var(--chart-5)",
  },
} satisfies ChartConfig

const channels = ["search", "social", "email", "referral", "direct"] as const

/** A bump chart of five channels' signup rank, January to June. Pointing at a line brings it forward. */
export function ChartBump() {
  // Pointing at a line brings it forward and fades the rest, so one path is easy to follow.
  const [active, setActive] = useState<string | null>(null)

  return (
    <Card>
      <CardHeader>
        <CardTitle>Bump Chart</CardTitle>
        <CardDescription>Signup rank by channel, January to June</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={chartConfig}>
          <LineChart
            accessibilityLayer
            data={chartData}
            margin={{ top: 12, left: 4, right: 12 }}
            onMouseLeave={() => setActive(null)}
          >
            <CartesianGrid vertical={false} />
            <XAxis
              dataKey="month"
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              tickFormatter={(value: string) => value.slice(0, 3)}
            />
            <YAxis
              reversed
              domain={[1, channels.length]}
              ticks={[1, 2, 3, 4, 5]}
              // Every rank keeps its tick, even when a short chart has little room.
              interval={0}
              allowDecimals={false}
              tickLine={false}
              axisLine={false}
              width={28}
              tickFormatter={(value: number) => `#${value}`}
            />
            <ChartTooltip cursor={false} content={<ChartTooltipContent />} />
            {channels.map((channel) => (
              <Line
                key={channel}
                dataKey={channel}
                type="bumpX"
                stroke={`var(--color-${channel})`}
                strokeWidth={active === channel ? 3 : 2}
                strokeOpacity={active === null || active === channel ? 1 : 0.2}
                dot={{ r: 4, fill: "var(--background)", strokeWidth: 2 }}
                activeDot={{ r: 5 }}
                onMouseEnter={() => setActive(channel)}
              />
            ))}
            <ChartLegend content={<ChartLegendContent />} />
          </LineChart>
        </ChartContainer>
      </CardContent>
      <CardFooter className="flex-col items-start gap-2 text-sm">
        <div className="leading-none font-medium">Social rose from third to first in March</div>
        <div className="leading-none text-muted-foreground">Rank by new signups each month</div>
      </CardFooter>
    </Card>
  )
}
